        var nxt = d4.next;
        var n23;
        if (pace === 'paced') { n23 = Math.floor((N - C.NY1[pace]) * C.NEXT_MULT[nxt]); }
        else { n23 = nxt === 'double' ? C.NY1[pace] : 0; }
        var k23 = nxt === 'double' ? 'rush' : k1;
        for (i = 0; i < n23; i++) { ch.push({ kind: k23, amt: ticket, px: 1.0, year: 2 + (i % 2), net: true, note: false }); }
        var f = d4.follow;
        if (f === 'bridge') { ch.push({ kind: 'bridge', amt: reserve > 0 ? reserve : C.BRIDGE_AMT, px: 1.0, year: 2, net: false, note: true }); }
        if (f === 'prorata' && n1 >= 1) { ch.push({ kind: 'win', amt: reserve > 0 ? reserve : ticket, px: 1.0, year: 2, net: true, note: false }); }
        return { ch: ch, B: B, ticket: ticket, reserve: reserve, n1: n1, n23: n23, iker: iker };
    }

    // Exact distribution of the total return in units of KEY euros (deterministic convolution, ascending integer keys).
    function distOf(ch) {
        var D = { 0: 1.0 };
        var j, i, k, keys, p, vals, N2, pk, nk;
        for (j = 0; j < ch.length; j++) {
            p = C.P[ch[j].kind];
            vals = [];
            for (i = 0; i < 5; i++) { vals.push(Math.round(ch[j].amt * ch[j].px * C.MULT[i] / C.KEY)); }
            N2 = {};
            keys = Object.keys(D).map(Number).sort(function(a, b) { return a - b; });
            for (k = 0; k < keys.length; k++) {
                pk = D[keys[k]];
                for (i = 0; i < 5; i++) {
                    if (p[i] <= 0) { continue; }
                    nk = keys[k] + vals[i];
                    N2[nk] = (N2[nk] || 0.0) + pk * p[i];
                }
            }
            D = N2;
        }
        return D;
    }

    function evaluate(dec) {
        var d1 = dec.round1;
        var d2 = dec.round2 || TEMPLATE.round2;
        var d3 = dec.round3 || TEMPLATE.round3;
        var d4 = dec.round4 || TEMPLATE.round4;
        var pf = portfolio(dec);
        var ch = pf.ch;
        var inv = 0, ev = 0, ndeals = 0, deals = 0;
        var j, c;
        for (j = 0; j < ch.length; j++) { inv += ch[j].amt; }
        for (j = 0; j < ch.length; j++) { ev += ch[j].amt * emult(ch[j].kind, ch[j].px); }
        for (j = 0; j < ch.length; j++) { if (ch[j].net) { ndeals += 1; } }
        for (j = 0; j < ch.length; j++) {
            c = ch[j].kind;
            if (c === 'iker' || c === 'net' || c === 'diy' || c === 'rush' || c === 'win') { deals += 1; }
        }
        var hours = C.DD_H[d2.dd] * deals;
        if (d2.cargo !== 'decline') { hours += C.CARGO_H; }
        if (pf.iker > 0 && d3.pacto === 'board') { hours += C.BOARD_H * C.YEARS; }
        var veh = d3.veh;
        var fees = 0.0;
        if (d2.dd === 'lead') { fees += C.NET_FEE * C.YEARS; }
        if (veh === 'direct') {
            fees += C.DIRECT_FEE * ndeals;
            hours += C.DIRECT_H * ndeals;
        } else if (veh === 'spv') {
            var gain = 0;
            for (j = 0; j < ch.length; j++) { if (ch[j].net) { gain += ch[j].amt * Math.max(0.0, emult(ch[j].kind, ch[j].px) - 1.0); } }
            fees += C.SPV_CARRY * gain;
        } else if (inv > 0) {
            fees += C.HOLD_SET + C.HOLD_YR * C.HOLD_YRS;
            hours += C.HOLD_H * C.YEARS;
        }
        var loan, emergUsed;
        if (d1.src === 'loan') {
            loan = inv;
            emergUsed = 0.0;
        } else {
            var first = d1.src === 'emergency' ? C.EMERG : C.SAVE;
            var fromFirst = Math.min(inv, first);
            var rest = inv - fromFirst;
            var second = d1.src === 'emergency' ? C.SAVE : C.EMERG;
            var fromSecond = Math.min(rest, second);
            loan = rest - fromSecond;
            emergUsed = d1.src === 'emergency' ? fromFirst : fromSecond;
        }
        var loanint = loan * C.LOAN_R * C.LOAN_Y;
        var cushion = (C.EMERG - emergUsed) / C.MONTH;
        var credit = 0.0;
        var improper = 0.0;
        var tax = d4.tax;
        var y, el, al, e, good, claimed, bad;
        for (y = 1; y <= 3; y++) {
            el = 0.0;
            al = 0.0;
            for (j = 0; j < ch.length; j++) {
                if (ch[j].year !== y) { continue; }
                al += ch[j].amt;
                e = 0.0;
                if (veh !== 'holding' && !ch[j].note) {
                    if (ch[j].net && veh === 'spv') { e = 0.0; }
                    else { e = C.ELIG[ch[j].kind]; }
                }
                el += ch[j].amt * e;
            }
            good = Math.min(C.DED * el, C.CUOTA);
            if (tax === 'proper') { credit += good; }
            else if (tax === 'all') {
                claimed = Math.min(C.DED * al, C.CUOTA);
                bad = Math.max(0.0, claimed - good);
                improper += bad;
                credit += good + (1.0 - C.CLAW) * bad;
            }
        }
        var nv = ev + credit - fees - loanint;
        var em = inv > 0 ? nv / inv : 1.0;
        var D = distOf(ch);
        var keys = Object.keys(D).map(Number).sort(function(a, b) { return a - b; });
        var cum = 0.0, q10 = 0, k;
        for (k = 0; k < keys.length; k++) {
            cum += D[keys[k]];
            if (cum >= 0.10 - 1e-12) { q10 = keys[k]; break; }
        }
        var q10e = q10 * C.KEY;
        var back = 0.0;
        for (k = 0; k < keys.length; k++) { if (keys[k] * C.KEY >= inv - 1e-9) { back += D[keys[k]]; } }
        var hit = 1.0;
        for (j = 0; j < ch.length; j++) { hit *= (1.0 - C.P[ch[j].kind][3] - C.P[ch[j].kind][4]); }
        hit = ch.length ? 1.0 - hit : 0.0;
        var loss = Math.max(0.0, inv - q10e - credit + fees + loanint);
        var lossp = 100.0 * loss / C.LIQ;
        var conflict = d2.cargo === 'invest' ? Math.min(pf.ticket, C.CARGO_MAX) : 0.0;
        return {
            inv: inv, ev: ev, credit: credit, fees: fees, loanint: loanint, hours: hours, nv: nv, em: em, q10: q10e, loss: loss, lossp: lossp,
            back: 100.0 * back, hit: 100.0 * hit, cushion: cushion, n: ch.length, improper: improper, conflict: conflict, loan: loan
        };
    }

    class MiPrimerCheque2424Adapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Mi Primer Cheque como Business Angel';
            this.version = '1.0.0';
            this.ROUNDS = [
                { panel: 'roundPanel1', nameKey: 'r1_name', briefKey: 'r1_brief' },
                { panel: 'roundPanel2', nameKey: 'r2_name', briefKey: 'r2_brief' },
                { panel: 'roundPanel3', nameKey: 'r3_name', briefKey: 'r3_brief' },
                { panel: 'roundPanel4', nameKey: 'r4_name', briefKey: 'r4_brief' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rounds: [],
                    periods: [],
                    conflictCum: 0,
                    improperCum: 0,
                    dec: {},
                    scoreHistory: [],
                    performance: { overallScore: 0 },
                    performanceTier: 'beginner'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }

        _syncControlsFromDecisions(state) {
            var raw = (state && state.decisions) || {};
            var saved = (state && state.domainState && state.domainState.dec) || {};
            var d = {
                round1: raw.round1 || saved.round1,
                round2: raw.round2 || saved.round2,
                round3: raw.round3 || saved.round3,
                round4: raw.round4 || saved.round4
            };
            var set = function(id, val) {
                var el = document.getElementById(id);
                if (el && val !== undefined && val !== null) { el.value = String(val); }
            };
            if (d.round1) { set('r1_bud', d.round1.bud); set('r1_src', d.round1.src); set('r1_pace', d.round1.pace); }
            if (d.round2) { set('r2_iker', d.round2.iker); set('r2_dd', d.round2.dd); set('r2_cargo', d.round2.cargo); }
            if (d.round3) { set('r3_val', d.round3.val); set('r3_pacto', d.round3.pacto); set('r3_veh', d.round3.veh); }
            if (d.round4) { set('r4_follow', d.round4.follow); set('r4_tax', d.round4.tax); set('r4_next', d.round4.next); }
        }

        _t(key, vars) {
            return window.mySimulation ? window.mySimulation.t(key, vars) : key;
        }

        _cl(key, fallback) {
            var s = this._t(key);
            return s === key ? fallback : s;
        }

        _lang() {
            return (window.mySimulation && window.mySimulation.language === 'en') ? 'en' : 'es';
        }

        // Spanish format in es (point thousands, comma decimals); English format in en.
        _fmtNum(v, dec) {
            var n = Number(v) || 0;
            var neg = n < 0;
            var f = Math.abs(n).toFixed(dec);
            var parts = f.split('.');
            var s = parts[0];
            var out = '';
            var th = this._lang() === 'en' ? ',' : '.';
            var dp = this._lang() === 'en' ? '.' : ',';
            while (s.length > 3) { out = th + s.slice(-3) + out; s = s.slice(0, -3); }
            out = s + out;
            if (parts.length > 1) { out = out + dp + parts[1]; }
            return (neg && Number(f) !== 0 ? '−' : '') + out;
        }

        // Whole euros: 1.234 € in es, EUR 1,234 in en.
        _fmtE(v) {
            var n = Number(v) || 0;
            var body = this._fmtNum(Math.abs(n), 0);
            var sign = (n < 0 && Math.abs(n) >= 0.5) ? '−' : '';
            if (this._lang() === 'en') { return sign + 'EUR ' + body; }
            return sign + body + ' €';
        }

        _fmtPct(v) {
            var x = this._fmtNum(Number(v) || 0, 1);
            return this._lang() === 'en' ? x + '%' : x + ' %';
        }

        _fmtX(v) {
            return this._fmtNum(Number(v) || 0, 2) + '×';
        }

        _updateBriefing(state) {
            var cur = (state && state.currentPeriod) || 1;
            var maxP = (state && state.maxPeriods) || this.ROUNDS.length;
            var done = (state && state.history) ? state.history.length : 0;
            var finished = done >= maxP || cur > this.ROUNDS.length;
            var i, panel;
            for (i = 0; i < this.ROUNDS.length; i++) {
                panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!finished && (i + 1) === cur) ? 'block' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var ps = ds.periods || [];
            var rounds = ds.rounds || [];
            var sEl = document.getElementById('semesterText');
            if (sEl) { sEl.innerHTML = ps.length ? this._periodHtml(ds, ps[ps.length - 1]) : this._t('sem_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.classList.remove('ea2424-warn');
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey !== 'ok') { fbEl.classList.add('ea2424-warn'); }
                }
            }
        }

        _periodHtml(ds, q) {
            var html = this._t('sem_body', {
                n: this._fmtNum(q.n, 0), inv: this._fmtE(q.inv), pct: this._fmtPct(100.0 * q.inv / C.LIQ), em: this._fmtX(q.em)
            });
            html += '<span class="ea2424-cases">' + this._t('s_dist', {
                q10: this._fmtE(q.q10), loss: this._fmtE(q.loss), lossp: this._fmtPct(q.lossp), back: this._fmtPct(q.back), hit: this._fmtPct(q.hit)
            }) + '</span>';
            html += '<span class="ea2424-cases">' + this._t('s_money', {
                cr: this._fmtE(q.credit), fe: this._fmtE(q.fees), li: this._fmtE(q.loanint), h: this._fmtNum(q.hours, 0)
            }) + '</span>';
            html += '<span class="ea2424-cases">' + this._t('s_cush', { m: this._fmtNum(q.cushion, 1) }) + '</span>';
            if (q.conflict > 0) { html += '<span class="ea2424-reveal">' + this._t('s_conflict', { a: this._fmtE(q.conflict) }) + '</span>'; }
            if (q.improper > 0) { html += '<span class="ea2424-reveal">' + this._t('s_improper', { a: this._fmtE(q.improper) }) + '</span>'; }
            var keys = ds.capKeys || [];
            var i;
            for (i = 0; i < keys.length; i++) {
                html += '<span class="ea2424-reveal">' + this._t(keys[i], { a: this._fmtE(keys[i] === 'cap_conflict' ? (ds.conflictCum || 0) : (ds.improperCum || 0)) }) + '</span>';
            }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: this._fmtNum(Math.round(r.pts * 10) / 10, 1) };
            return '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            if (period === 1) {
                var bud = this._readSelect('r1_bud', CTRL.round1.bud);
                var src = this._readSelect('r1_src', CTRL.round1.src);
                var pace = this._readSelect('r1_pace', CTRL.round1.pace);
                if (!bud || !src || !pace) { return warn('warn_r1'); }
                decisions.round1 = { bud: bud, src: src, pace: pace };
                return true;
            }
            if (period === 2) {
                var iker = this._readSelect('r2_iker', CTRL.round2.iker);
                var dd = this._readSelect('r2_dd', CTRL.round2.dd);
                var cargo = this._readSelect('r2_cargo', CTRL.round2.cargo);
                if (!iker || !dd || !cargo) { return warn('warn_r2'); }
                decisions.round2 = { iker: iker, dd: dd, cargo: cargo };
                return true;
            }
            if (period === 3) {
                var val = this._readSelect('r3_val', CTRL.round3.val);
                var pacto = this._readSelect('r3_pacto', CTRL.round3.pacto);
                var veh = this._readSelect('r3_veh', CTRL.round3.veh);
                if (!val || !pacto || !veh) { return warn('warn_r3'); }
                decisions.round3 = { val: val, pacto: pacto, veh: veh };
                return true;
            }
            if (period === 4) {
                var follow = this._readSelect('r4_follow', CTRL.round4.follow);
                var tax = this._readSelect('r4_tax', CTRL.round4.tax);
                var next = this._readSelect('r4_next', CTRL.round4.next);
                if (!follow || !tax || !next) { return warn('warn_r4'); }
                decisions.round4 = { follow: follow, tax: tax, next: next };
                return true;
            }
            return warn('warn_finished');
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every decision is re-evaluated from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var periods = [];
            var total = 0.0;
            var cap = 100.0;
            var r, known, q, rub, ov, osf, pts;
            for (r = 1; r <= period; r++) {
                known = knownUpTo(d, r);
                q = evaluate(known);
                q.t = r;
                rub = this._rubric(known, r);
                ov = C.W_EM * clamp((q.em - C.EM_LO[r - 1]) / (C.EM_HI[r - 1] - C.EM_LO[r - 1]), 0.0, 1.0);
                osf = C.W_SAFE * clamp((C.LOSS_HI - q.lossp) / (C.LOSS_HI - C.LOSS_LO), 0.0, 1.0) * clamp(q.cushion / 6.0, 0.0, 1.0);
                pts = rub + ov + osf;
                total += pts;
                cap = 100.0;
                if (r >= 2 && q.conflict > 0) { cap = Math.min(cap, Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPC_W * q.conflict)); }
                if (r >= 4 && q.improper > 0) { cap = Math.min(cap, Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPT_W * q.improper)); }
                periods.push(q);
                rounds.push({ period: r, rub: rub, ov: ov, osf: osf, pts: pts, verdictKey: this._verdict(known, r) });
            }
            var last = periods[periods.length - 1];
            ds.rounds = rounds;
            ds.periods = periods;
            ds.conflictCum = period >= 2 ? last.conflict : 0;
            ds.improperCum = period >= 4 ? last.improper : 0;
            ds.total = total;
            ds.cap = cap;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (ds.conflictCum > 0 && total > Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPC_W * ds.conflictCum)) { ds.capKeys.push('cap_conflict'); }
            if (ds.improperCum > 0 && total > Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPT_W * ds.improperCum)) { ds.capKeys.push('cap_tax'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                inv: Math.round(last.inv),
                em: Math.round(last.em * 100) / 100,
                back: Math.round(last.back * 10) / 10,
                loss: Math.round(last.loss),
                cush: Math.round(last.cushion * 10) / 10,
                score: score,
                overallScore: score
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d = dec['round' + r];
            var keys = Object.keys(CTRL['round' + r]);
            var s = 0, i;
            for (i = 0; i < keys.length; i++) { s += P[keys[i] + r][d[keys[i]]]; }
            return s;
        }

        _verdict(dec, r) {
            var d = dec['round' + r];
            var order = VORDER[r];
            var i;
            for (i = 0; i < order.length; i++) {
                if (d[order[i][0]] === order[i][1]) { return order[i][1]; }
            }
            return 'ok';
        }

        _composite(ds) {
            var total = Math.min((ds && typeof ds.cap === 'number') ? ds.cap : 100, (ds && ds.total) || 0);
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        setupUI(uiManager) {
            var self = this;
            var lastP = function(ds) { var ps = (ds && ds.periods) || []; return ps.length ? ps[ps.length - 1] : null; };
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('invDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtE(q.inv) : '—'; });
            uiManager.bind('emDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtX(q.em) : '—'; });
            uiManager.bind('backDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtPct(q.back) : '—'; });
            uiManager.bind('lossDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtE(q.loss) : '—'; });
            uiManager.bind('cushDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtNum(q.cushion, 1) : '—'; });
            uiManager.bind('hitDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtPct(q.hit) : '—'; });
        }

        getChartConfig() {
            var t = this._t.bind(this);
            var sp = t('s_shortp');
            return {
                emChart: {
                    type: 'bar',
                    data: {
                        labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
