        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var ps = ds.periods || [];
            var hist = ds.scoreHistory || [];
            var data = [0, 0, 0, 0];
            var sp = this._t('s_shortp');
            var i;
            for (i = 0; i < ps.length && i < 4; i++) { data[i] = Math.round(ps[i].em * 100) / 100; }
            return {
                emChart: {
                    labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                    datasets: [{ data: data, label: this._t('chart_dataset') + (hist.length ? ' · ' + sp + hist.length : '') }]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundPoints', label: 'Points', i18nKey: 'col_points' },
                { key: 'results.inv', label: 'Committed', i18nKey: 'col_inv', formatter: function(v) { return self._fmtE(v); } },
                { key: 'results.em', label: 'Expected value', i18nKey: 'col_em', formatter: function(v) { return self._fmtX(v); } },
                { key: 'results.back', label: 'Money back', i18nKey: 'col_back', formatter: function(v) { return self._fmtPct(v); } },
                { key: 'results.loss', label: 'Loss 1 in 10', i18nKey: 'col_loss', formatter: function(v) { return self._fmtE(v); } },
                { key: 'results.cush', label: 'Cushion', i18nKey: 'col_cush', formatter: function(v) { return self._fmtNum(v, 1); } },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ps = ds.periods || [];
            var score = this._composite(ds);
            var performance = 'Beginner';
            if (score >= 55) { performance = 'Good'; }
            if (score >= 75) { performance = 'Excellent'; }
            var q = ps.length ? ps[ps.length - 1] : { inv: 0, em: 1, back: 0, loss: 0, lossp: 0, cushion: 6, hit: 0 };
            var insights = [];
            insights.push(q.lossp <= C.SIZE_OK ? this._t('insight_size_ok') : this._t('insight_size_bad'));
            insights.push(q.back >= C.BACK_OK ? this._t('insight_div_ok') : this._t('insight_div_bad'));
            insights.push(q.em > C.INDEX ? this._t('insight_em_ok') : this._t('insight_em_bad'));
            insights.push(q.cushion >= 6.0 ? this._t('insight_cush_ok') : this._t('insight_cush_bad'));
            insights.push((ds.conflictCum || 0) > 0 ? this._t('insight_conflict_bad') : this._t('insight_conflict_ok'));
            insights.push((ds.improperCum || 0) > 0 ? this._t('insight_tax_bad') : this._t('insight_tax_ok'));
            insights.push(this._t('insight_next'));
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                inv: q.inv,
                em: q.em,
                back: q.back,
                loss: q.loss,
                conflict: ds.conflictCum || 0,
                improper: ds.improperCum || 0,
                rounds: (ds.scoreHistory || []).length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ea2424-cm">'
                + '<div class="ea2424-cm-score">' + score + '<span class="ea2424-cm-max">/100</span></div>'
                + '<div class="ea2424-cm-verdict">' + (s.performanceLabel || s.performance || '') + '</div>'
                + '<div class="ea2424-cm-kpis">'
                + '<div class="ea2424-cm-kpi">' + this._t('cm_kpi_inv') + '<strong>' + this._fmtE(s.inv) + '</strong></div>'
                + '<div class="ea2424-cm-kpi">' + this._t('cm_kpi_em') + '<strong>' + this._fmtX(s.em) + '</strong></div>'
                + '<div class="ea2424-cm-kpi">' + this._t('cm_kpi_back') + '<strong>' + this._fmtPct(s.back) + '</strong></div>'
                + '<div class="ea2424-cm-kpi">' + this._t('cm_kpi_loss') + '<strong>' + this._fmtE(s.loss) + '</strong></div>'
                + '</div>'
                + '<div class="ea2424-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ea2424-cm-insights">' + items + '</ul>'
                + '</div>';
        }

